const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const startDate = '2009-08-03';
  const endDate = '2009-08-09'; // Exclusive, so this covers August 3-8. For August 9, it needs to be '2009-08-10'.
  // Adjust endDate to include August 9.
  const actualEndDate = '2009-08-10'; // Filters up to, but not including, this date. So August 3-9.

  // Define Northern and Southern Taiwan polygons.
  // Using a simplified split around 24 degrees North latitude.
  const northernTaiwan = ee.Geometry.Polygon({
    coords: [
      [120.0, 24.0],
      [120.0, 25.5],
      [122.5, 25.5],
      [122.5, 24.0],
      [120.0, 24.0]
    ],
    geodesic: false
  });

  const southernTaiwan = ee.Geometry.Polygon({
    coords: [
      [120.0, 21.5],
      [120.0, 24.0],
      [122.5, 24.0],
      [122.5, 21.5],
      [120.0, 21.5]
    ],
    geodesic: false
  });

  const scale = 3000; // TRMM resolution is ~25km, so a scale of 3000m is appropriate.

  // 2. Data Acquisition & Check
  const trmm = ee.ImageCollection('TRMM/3B42RT/V7')
    .filterDate(startDate, actualEndDate)
    .select('precipitation');

  const trmmSize = await trmm.size().getInfo();
  if (trmmSize === 0) {
    console.log("No TRMM 3B42RT V7 images found for the specified date range.");
    console.log("C1");
    return;
  }
  console.log(`TRMM images found: ${trmmSize}`);

  // Sum precipitation over the period (mm/hour * number of hours in a day * number of days)
  // TRMM data is accumulated daily in mm/hour. Summing directly results in total mm/hour over the period.
  // To get total precipitation in mm for the period, we sum the daily images,
  // then multiply by the time step (e.g., if daily is sum of 3-hour, then need to adjust).
  // TRMM 3B42RT is daily accumulation in mm/hour, so summing these images will give total mm/hour * 7 days.
  // To get total mm, we need to consider the unit is mm/hr, and each image represents a 24-hr accumulation,
  // so the value in the band 'precipitation' is already the daily total in mm/day.
  // Wait, the documentation says "Precipitation (mm/hour)". So if we sum 7 daily images, we get (mm/hour) * 7.
  // To convert this to total mm, we should multiply by 24 (hours per day).
  // No, actually, for TRMM 3B42RT, the value is instantaneous mm/hour. To get daily total mm, multiply by 24.
  // But common practice is to just sum the 'precipitation' band directly over time to get accumulated rainfall in mm.
  // Let's assume the 'precipitation' band for each daily image represents the daily average mm/hour.
  // So, sum_daily_avg_mm_per_hour * 24 * num_days = total mm.
  // Let's simplify and just sum the daily images, which would result in cumulative average mm/hour.
  // The comparison will still be valid even if the absolute units are slightly off, as long as consistent.
  // A safer approach is to treat the 'precipitation' band as average mm/hr for that day,
  // so each image represents 24 * avg_mm/hr_for_that_day = daily total mm.
  // Summing these would give total mm over the period.

  // Correct approach: Each image's 'precipitation' band has units of mm/hour.
  // To get total mm over the period, we sum the daily images and multiply by 24 (hours in a day).
  const totalPrecipitation_mm_per_hour = trmm.sum();

  // If the totalPrecipitation_mm_per_hour image is empty (e.g., no data intersection)
  const countPixels = await totalPrecipitation_mm_per_hour.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: northernTaiwan.union(southernTaiwan),
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  if (countPixels === 0 || countPixels === null) {
    console.log("No valid pixels after summing TRMM data across the regions.");
    console.log("C2");
    return;
  }
  console.log(`Valid pixels in combined region: ${countPixels}`);

  // Calculate total accumulated precipitation in mm for Northern Taiwan
  const northernPrecipitation_mm_per_hour = await totalPrecipitation_mm_per_hour.reduceRegion({
    reducer: ee.Reducer.mean(), // Mean mm/hour over the northern region for the accumulated period.
    geometry: northernTaiwan,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // Calculate total accumulated precipitation in mm for Southern Taiwan
  const southernPrecipitation_mm_per_hour = await totalPrecipitation_mm_per_hour.reduceRegion({
    reducer: ee.Reducer.mean(), // Mean mm/hour over the southern region for the accumulated period.
    geometry: southernTaiwan,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 4. Calculation and Validation
  if (northernPrecipitation_mm_per_hour === null || southernPrecipitation_mm_per_hour === null ||
      isNaN(northernPrecipitation_mm_per_hour) || isNaN(southernPrecipitation_mm_per_hour)) {
    console.log("Failed to retrieve precipitation values for one or both regions.");
    console.log("C3");
    return;
  }

  // Multiply by 24 (hours) and 7 (days) to get approximate total mm accumulated per region,
  // assuming the "precipitation" band is the average mm/hour for the day.
  // If the 'precipitation' band is already the daily total in mm, then just sum.
  // Given the description 'mm/hour', summing 7 daily values gives cumulative mm/hour.
  // To get total mm, we multiply by 24 hours/day * 7 days.
  // No, if each image is daily average mm/hour, and we sum them, we get sum(avg_mm/hour).
  // To get total mm: (sum_of_daily_avg_mm_per_hour) * 24 hours.
  // Since there are 7 images (7 days), the sum represents the sum of average daily mm/hour for those 7 days.
  // So, to get total mm of rainfall, it would be: (sum of avg daily mm/hour) * 24.
  // Let's use this interpretation for 'total rainfall'.

  const daysInPeriod = 7; // Aug 3 to Aug 9 inclusive
  const totalNorthernPrecipitation_mm = northernPrecipitation_mm_per_hour * 24 * daysInPeriod;
  const totalSouthernPrecipitation_mm = southernPrecipitation_mm_per_hour * 24 * daysInPeriod;

  console.log(`Northern Taiwan total precipitation (mm): ${totalNorthernPrecipitation_mm.toFixed(2)}`);
  console.log(`Southern Taiwan total precipitation (mm): ${totalSouthernPrecipitation_mm.toFixed(2)}`);

  // 5. Final Answer
  if (totalSouthernPrecipitation_mm > totalNorthernPrecipitation_mm) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
